/// Fills the workbench colors from the UI theme; unmapped fields keep `c`'s value.
pub(in crate::theme) fn colors(mut c: Colors) -> Colors {
    c.frame = px(0xE9EAEEFF); // MainWindow.background
    c.island = px(0xFFFFFFFF); // ToolWindow.background
    c.popup = px(0xFFFFFFFF); // Popup.background
    c.popup_border = px(0xD1D3D9FF); // Popup.borderColor
    c.field = px(0xFFFFFFFF); // TextField.background
    c.notification = px(0xFFFFFFFF); // Notification.background
    c.tooltip = px(0xFFFFFFFF); // ToolTip.background
    c.text = px(0x000000FF); // Label.foreground
    c.text_strong = px(0x000000FF); // Label.foreground
    c.text_secondary = px(0x5F6269FF); // StatusBar.Widget.foreground
    c.text_placeholder = px(0x73767CFF); // Component.infoForeground
    c.text_disabled = px(0x9FA2A8FF); // Label.disabledForeground
    c.text_on_accent = px(0xFFFFFFFF); // Button.default.foreground
    c.hover = px(0x00000012); // ActionButton.hoverBackground
    c.pressed = px(0x00000020); // ActionButton.pressedBackground
    c.selection = px(0xD0DFFEFF); // List.selectionBackground
    c.selection_popup = px(0xD0DFFEFF); // CompletionPopup.selectionBackground
    c.accent = px(0x3871E1FF); // Button.default.startBackground
    c.focus_ring = px(0x3871E1FF); // Component.focusColor
    c.border = px(0xD1D3D9FF); // Component.borderColor
    c.separator = px(0x00000020); // MainToolbar.separatorColor
    c.group_separator = px(0xE9EAEEFF); // Menu.separatorColor
    c.tab_selected = px(0xE3EBFEFF); // EditorTabs.underlinedTabBackground
    c.tab_selected_border = px(0xA7C5FFFF); // EditorTabs.underlinedBorderColor
    c.tab_text = px(0x404040FF); // mix(self:text, self:island, num:EditorTabs.unselectedAlpha)
    c.control_border = px(0xC3C5CBFF); // ToggleButton.borderColor
    c.toggle_on = px(0x4E9D6CFF); // ToggleButton.onBackground
    c.toggle_off = px(0xF7F8F9FF); // ToggleButton.offBackground
    c.toggle_off_knob = px(0xC3C5CBFF); // ToggleButton.buttonColor
    c.border_disabled = px(0xDDDFE4FF); // Button.disabledBorderColor
    c.control_selected = px(0x3871E1FF); // Button.default.startBackground
    c.selection_inactive = px(0xE9EAEEFF); // List.selectionInactiveBackground
    c.row_hover = px(0x00000008); // List.hoverBackground
    c.combo = px(0xFFFFFFFF); // ComboBox.ArrowButton.nonEditableBackground
    c.combo_arrow = px(0x6E6E6EFF); // ComboBox.ArrowButton.iconColor
    c.segment_selected = px(0xFFFFFFFF); // SegmentedButton.selectedButtonColor
    c.segment_selected_border = px(0xB5B7BDFF); // SegmentedButton.selectedStartBorderColor
    c.progress_track = px(0xDDDFE4FF); // ProgressBar.trackColor
    c.counter = px(0x8B8E94FF); // Counter.background
    c.counter_text = px(0xFFFFFFFF); // Counter.foreground
    c.tag = px(0xEBECF0FF); // Tag.background
    c.error = px(0xC54E58FF); // Label.errorForeground
    c.warning = px(0xA56906FF); // Label.warningForeground
    c.success = px(0x338555FF); // Label.successForeground
    c.link = px(0x2F5EB9FF); // Link.activeForeground
    c.banner_info.background = px(0xF7F8FFFF); // Banner.infoBackground
    c.banner_info.border = px(0xBDD3FFFF); // Banner.infoBorderColor
    c.banner_warning.background = px(0xFFF6E9FF); // Banner.warningBackground
    c.banner_warning.border = px(0xF4CD9AFF); // Banner.warningBorderColor
    c.banner_error.background = px(0xFFF6F5FF); // Banner.errorBackground
    c.banner_error.border = px(0xFFC4C5FF); // Banner.errorBorderColor
    c.banner_success.background = px(0xF5FAF3FF); // Banner.successBackground
    c.banner_success.border = px(0xBBDBC2FF); // Banner.successBorderColor
    c.run = px(0x369650FF); // RunWidget.runIconColor
    c.stop = px(0xE4656EFF); // RunWidget.stopBackground
    c.vcs_modified = px(0x0033B3FF); // scheme FILESTATUS_MODIFIED
    c.vcs_added = px(0x067D17FF); // scheme FILESTATUS_ADDED
    c.vcs_untracked = px(0xB23247FF); // scheme FILESTATUS_UNKNOWN
    c.vcs_ignored = px(0x6C707EFF); // scheme FILESTATUS_DELETED
    c.selection_text = px(0x000000FF); // List.selectionForeground
    c.selection_text_inactive = px(0x000000FF); // List.selectionInactiveForeground
    c.divider = px(0xE9EAEEFF); // Borders.color
    c.header_active = px(0xF7F8F9FF); // ToolWindow.Header.background
    c.header_inactive = px(0xFFFFFFFF); // ToolWindow.Header.inactiveBackground
    c.button_start = px(0xFFFFFFFF); // Button.startBackground
    c.button_end = px(0xFFFFFFFF); // Button.endBackground
    c.accent_end = px(0x3871E1FF); // Button.default.endBackground
    // Kept at the measured value: accent_disabled, text_on_accent_disabled, tab_scroll_thumb, tab_scroll_thumb_hover, control, clear_icon, clear_icon_hover, clear_hover, icon, folder_fill.
    c
}
